grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.cash_reconciliation_resolutions(id uuid primary key default gen_random_uuid(),reconciliation_id uuid not null references finance_private.cash_reconciliations(id),version integer not null,current_ledger_balance_minor bigint not null,correction_transaction_ids uuid[] not null,evidence_file_id uuid not null references app_private.files(id),reason text not null,resolved_by uuid not null references app_private.accounts(id),resolved_at timestamptz not null default now(),command_id uuid not null unique,unique(reconciliation_id,version));
alter table finance_private.cash_reconciliation_resolutions enable row level security;
create policy commands_access on finance_private.cash_reconciliation_resolutions to git_tutor_commands using(true)with check(true);
revoke all on finance_private.cash_reconciliation_resolutions from public,anon,authenticated,service_role,git_tutor_worker;
grant select,insert on finance_private.cash_reconciliation_resolutions to git_tutor_commands;
create trigger immutable_row before update or delete on finance_private.cash_reconciliation_resolutions for each row execute function app_private.reject_immutable_change();

create function api.resolve_cash_reconciliation(p_reconciliation_id uuid,p_correction_transaction_ids uuid[],p_evidence_file_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;r finance_private.cash_reconciliations%rowtype;v integer;current_balance bigint;correction_total numeric;source_count integer;resolution uuid:=gen_random_uuid();begin
 perform app_private.require_role(actor,'admin');select *into r from finance_private.cash_reconciliations where id=p_reconciliation_id;if r.id is null then raise exception'NOT_FOUND';end if;
 perform app_private.payment_assert_file(p_evidence_file_id,'cash_reconciliation','receiving_account',r.receiving_account_id,actor);
 if p_reason is null or length(btrim(p_reason))not between 1 and 2000 or p_correction_transaction_ids is null or cardinality(p_correction_transaction_ids)not between 1 and 100 or array_position(p_correction_transaction_ids,null)is not null or(select count(distinct id)from unnest(p_correction_transaction_ids)id)<>cardinality(p_correction_transaction_ids)then raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,'resolve_cash_reconciliation',jsonb_build_object('reconciliation_id',p_reconciliation_id,'correction_transaction_ids',p_correction_transaction_ids,'evidence_file_id',p_evidence_file_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 perform pg_advisory_xact_lock(hashtextextended('cash-control:'||r.id,0));select coalesce(max(version),1)into v from finance_private.cash_reconciliation_resolutions where reconciliation_id=r.id;if v is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;
 select finance_private.finance_safe_total(coalesce(sum(l.signed_minor),0)),coalesce(sum(l.signed_minor)filter(where t.id=any(p_correction_transaction_ids)and t.recorded_at>r.posted_as_of),0),count(distinct t.id)filter(where t.id=any(p_correction_transaction_ids)and t.recorded_at>r.posted_as_of)into current_balance,correction_total,source_count from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.account_code='channel_cash'and l.receiving_account_id=r.receiving_account_id and t.effective_at<=r.balance_at and t.recorded_at<=now();
 if current_balance<>r.observed_balance_minor or correction_total<>r.difference_minor or source_count<>cardinality(p_correction_transaction_ids)then raise exception'STATE_CONFLICT';end if;
 if r.difference_minor=0 and not exists(select 1 from finance_private.cash_reconciliation_resolutions where reconciliation_id=r.id)then raise exception'STATE_CONFLICT';end if;
 v:=v+1;insert into finance_private.cash_reconciliation_resolutions(id,reconciliation_id,version,current_ledger_balance_minor,correction_transaction_ids,evidence_file_id,reason,resolved_by,command_id)values(resolution,r.id,v,current_balance,p_correction_transaction_ids,p_evidence_file_id,btrim(p_reason),actor,(ctx->>'command_id')::uuid);
 return app_private.booking_finish(ctx,r.id,v,jsonb_build_object('resolution_id',resolution,'state','resolved','current_ledger_balance_minor',current_balance),'cash_reconciliation_resolved',jsonb_build_object('reconciliation_id',r.id,'resolution_id',resolution));
end$$;
create function api.list_cash_reconciliations(p_receiving_account_id uuid default null,p_state text default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('matched','open','resolved','reopened'))then raise exception'VALIDATION_ERROR';end if;
 with rows as(select r.*,current_balance.amount current_balance,latest.id resolution_id,latest.version resolution_version,latest.resolved_at,latest.resolved_by,latest.evidence_file_id resolution_evidence,latest.reason resolution_reason,latest.correction_transaction_ids,case when latest.id is not null then case when current_balance.amount=r.observed_balance_minor then'resolved'else'reopened'end when r.difference_minor=0 and current_balance.amount=r.observed_balance_minor then'matched'else'open'end control_state from finance_private.cash_reconciliations r left join lateral(select *from finance_private.cash_reconciliation_resolutions rr where rr.reconciliation_id=r.id order by rr.version desc limit 1)latest on true cross join lateral(select finance_private.finance_safe_total(coalesce(sum(l.signed_minor),0))amount from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.account_code='channel_cash'and l.receiving_account_id=r.receiving_account_id and t.effective_at<=r.balance_at and t.recorded_at<=now())current_balance where(p_receiving_account_id is null or r.receiving_account_id=p_receiving_account_id)and(p_cursor is null or r.id>p_cursor))
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select id,jsonb_build_object('reconciliation_id',id,'receiving_account_id',receiving_account_id,'balance_at',balance_at,'posted_as_of',posted_as_of,'observed_balance_minor',observed_balance_minor,'ledger_balance_minor',ledger_balance_minor,'difference_minor',difference_minor,'current_ledger_balance_minor',current_balance,'current_difference_minor',finance_private.finance_safe_total(observed_balance_minor::numeric-current_balance),'owner_account_id',owner_account_id,'reason',reason,'state',control_state,'version',coalesce(resolution_version,1),'resolution',case when resolution_id is null then null else jsonb_build_object('resolution_id',resolution_id,'resolved_at',resolved_at,'resolved_by',resolved_by,'evidence_file_id',resolution_evidence,'reason',resolution_reason,'correction_transaction_ids',correction_transaction_ids)end)item from rows where p_state is null or control_state=p_state order by id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'reconciliation_id'else null end);
end$$;

create function api.list_cash_reconciliation_sources(p_reconciliation_id uuid,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();r finance_private.cash_reconciliations%rowtype;items jsonb;begin
 perform app_private.require_role(actor,'admin');select *into r from finance_private.cash_reconciliations where id=p_reconciliation_id;if r.id is null then raise exception'NOT_FOUND';end if;if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select t.id,jsonb_build_object('transaction_id',t.id,'source_type',t.source_type,'source_id',t.source_id,'effective_at',t.effective_at,'recorded_at',t.recorded_at,'cash_delta_minor',finance_private.finance_safe_total(sum(l.signed_minor)))item from finance_private.ledger_transactions t join finance_private.ledger_lines l on l.transaction_id=t.id where l.account_code='channel_cash'and l.receiving_account_id=r.receiving_account_id and t.effective_at<=r.balance_at and t.recorded_at>r.posted_as_of and t.recorded_at<=now()and(p_cursor is null or t.id>p_cursor)group by t.id order by t.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'transaction_id'else null end);
end$$;
create function finance_private.finance_tutor_lines(p_end timestamptz,p_as_of timestamptz)returns table(line_id uuid,tutor_id uuid,signed_minor bigint)language sql stable security definer set search_path='' as $$
 with sources as(select ledger_transaction_id,tutor_id from finance_private.tutor_earnings union select a.ledger_transaction_id,e.tutor_id from finance_private.earning_adjustments a join finance_private.tutor_earnings e on e.id=a.earning_id union select o.ledger_transaction_id,p.tutor_id from finance_private.payout_outcomes o join finance_private.payout_attempts p on p.id=o.payout_attempt_id where o.outcome='settled' union select r.ledger_transaction_id,p.tutor_id from finance_private.payout_reversals r join finance_private.payout_attempts p on p.id=r.payout_attempt_id)
 select l.id,s.tutor_id,l.signed_minor from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id left join sources s on s.ledger_transaction_id=t.id where l.account_code='tutor_payable'and t.effective_at<p_end and t.recorded_at<=p_as_of
$$;
alter function api.get_finance_summary(date,date,timestamptz)rename to get_finance_summary_pre_gross;
create function api.get_finance_summary(p_from date,p_to date,p_as_of timestamptz)returns jsonb language plpgsql security definer set search_path='' as $$declare report jsonb;end_at timestamptz;gross numeric;advance numeric;unattributed numeric;begin
 report:=api.get_finance_summary_pre_gross(p_from,p_to,p_as_of);select period_end into end_at from finance_private.finance_report_range(p_from,p_to,p_as_of);
 with balances as(select tutor_id,-sum(signed_minor)amount from finance_private.finance_tutor_lines(end_at,p_as_of)group by tutor_id)select coalesce(sum(greatest(amount,0))filter(where tutor_id is not null),0),coalesce(sum(greatest(-amount,0))filter(where tutor_id is not null),0),coalesce(sum(amount)filter(where tutor_id is null),0)into gross,advance,unattributed from balances;
 return jsonb_set(report,'{balances}',report->'balances'||jsonb_build_object('gross_tutor_payable_minor',finance_private.finance_json_total(gross),'tutor_advance_minor',finance_private.finance_json_total(advance),'unattributed_tutor_net_minor',finance_private.finance_json_total(unattributed)));
end$$;
create function api.list_tutor_obligations(p_from date,p_to date,p_as_of timestamptz,p_tutor_id uuid default null,p_side text default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();end_at timestamptz;items jsonb;begin
 perform app_private.require_role(actor,'admin');select period_end into end_at from finance_private.finance_report_range(p_from,p_to,p_as_of);if p_limit is null or p_limit not between 1 and 100 or(p_side is not null and p_side not in('payable','advance'))then raise exception'VALIDATION_ERROR';end if;
 with balances as(select tutor_id,-sum(signed_minor)amount from finance_private.finance_tutor_lines(end_at,p_as_of)where tutor_id is not null group by tutor_id)
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select t.id,jsonb_build_object('tutor_id',t.id,'tutor_name',p.display_name,'net_payable_minor',finance_private.finance_json_total(b.amount),'payable_minor',finance_private.finance_json_total(greatest(b.amount,0)),'advance_minor',finance_private.finance_json_total(greatest(-b.amount,0)))item from balances b join app_private.tutors t on t.id=b.tutor_id join app_private.accounts a on a.id=t.account_id join app_private.people p on p.id=a.person_id where(p_tutor_id is null or t.id=p_tutor_id)and(p_side is null or(p_side='payable'and b.amount>0)or(p_side='advance'and b.amount<0))and(p_cursor is null or t.id>p_cursor)order by t.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'tutor_id'else null end);
end$$;
create function api.list_tutor_obligation_entries(p_from date,p_to date,p_as_of timestamptz,p_tutor_id uuid,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();end_at timestamptz;items jsonb;begin
 perform app_private.require_role(actor,'admin');select period_end into end_at from finance_private.finance_report_range(p_from,p_to,p_as_of);if p_tutor_id is null or p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select l.id,jsonb_build_object('line_id',l.id,'transaction_id',t.id,'source_type',t.source_type,'source_id',t.source_id,'account_code',l.account_code,'signed_minor',l.signed_minor,'currency',l.currency,'effective_at',t.effective_at,'recorded_at',t.recorded_at,'charge_id',l.charge_id,'enrollment_id',l.enrollment_id,'receiving_account_id',l.receiving_account_id)item from finance_private.finance_tutor_lines(end_at,p_as_of)owned join finance_private.ledger_lines l on l.id=owned.line_id join finance_private.ledger_transactions t on t.id=l.transaction_id where owned.tutor_id=p_tutor_id and(p_cursor is null or l.id>p_cursor)order by l.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'line_id'else null end);
end$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','finance_private')and p.proname in('resolve_cash_reconciliation','list_cash_reconciliations','list_cash_reconciliation_sources','finance_tutor_lines','get_finance_summary_pre_gross','get_finance_summary','list_tutor_obligations','list_tutor_obligation_entries')loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'and f.proname<>'get_finance_summary_pre_gross'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
